Column(
    modifier = Modifier
        .widthIn(max = 300.dp)
        .clip(MonarchTheme.shapes.lg)
        .background(MonarchTheme.colors.bgSurface)
        .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg),
) {
    // The active speaker, as the web card shows them.
    Box(
        modifier = Modifier.fillMaxWidth().height(150.dp).background(MonarchTheme.colors.bgMuted),
        contentAlignment = Alignment.Center,
    ) {
        Box(Modifier.border(3.dp, MonarchTheme.colors.successSolid, CircleShape).padding(3.dp)) {
            MonarchAvatar(image = null, name = "Robin Park", size = MonarchAvatarSize.Lg, decorative = true)
        }
        Column(modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth()) {
            Box(Modifier.fillMaxWidth().height(2.dp).background(MonarchTheme.colors.successSolid))
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MonarchTheme.colors.bgInverse)
                    .padding(horizontal = MonarchTheme.spacing.space2, vertical = MonarchTheme.spacing.space1),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(text = "Robin Park", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textInverse, modifier = Modifier.weight(1f))
                // The signal strength, as the web card shows it.
                Row(horizontalArrangement = Arrangement.spacedBy(1.dp), verticalAlignment = Alignment.Bottom) {
                    listOf(6, 9, 12).forEach { bar ->
                        Box(Modifier.width(3.dp).height(bar.dp).background(MonarchTheme.colors.successStrong))
                    }
                }
            }
        }
    }
    Row(
        modifier = Modifier.fillMaxWidth().padding(MonarchTheme.spacing.space3),
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = "12:00", style = MonarchTextStyle.Caption)
        MonarchText(text = "4 in call", style = MonarchTextStyle.Caption, modifier = Modifier.weight(1f))
        MonarchIconButton(
            label = if (micOn) "Mute" else "Unmute",
            onClick = { micOn = !micOn },
            variant = MonarchButtonVariant.Secondary,
            icon = { MonarchIcon(if (micOn) SampleIcons.Mic else SampleIcons.MicOff, contentDescription = null) },
        )
        MonarchIconButton(
            label = "Expand",
            onClick = {},
            variant = MonarchButtonVariant.Secondary,
            icon = { MonarchIcon(SampleIcons.Expand, contentDescription = null) },
        )
        MonarchIconButton(
            label = "Leave call",
            onClick = {},
            variant = MonarchButtonVariant.Primary,
            icon = { MonarchIcon(SampleIcons.CallEnd, contentDescription = null) },
        )
    }
}

